     1	package pousada.report;
     2	
     3	import java.time.YearMonth;
     4	import java.time.format.DateTimeParseException;
     5	import java.util.Comparator;
     6	import java.util.List;
     7	import pousada.domain.Reservation;
     8	import pousada.error.BusinessException;
     9	import pousada.error.ErrorCode;
    10	import pousada.service.ReservationRepository;
    11	
    12	/** Base dos relatórios que olham as reservas que começam em um mês. */
    13	abstract class MonthlyReport implements Report {
    14	    private final ReservationRepository repository;
    15	
    16	    MonthlyReport(ReservationRepository repository) {
    17	        this.repository = repository;
    18	    }
    19	
    20	    @Override
    21	    public String parameter() {
    22	        return "month";
    23	    }
    24	
    25	    @Override
    26	    public ReportData generate(String period) {
    27	        return generate(parse(period));
    28	    }
    29	
    30	    abstract ReportData generate(YearMonth month);
    31	
    32	    /** Reservas que começam no mês, em ordem de entrada e depois de número. */
    33	    List<Reservation> startingIn(YearMonth month) {
    34	        return repository.all().stream()
    35	                .filter(r -> YearMonth.from(r.checkIn()).equals(month))
    36	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparing(Reservation::id))
    37	                .toList();
    38	    }
    39	
    40	    /** Reservas do mês que deixaram dinheiro com a pousada. */
    41	    List<Reservation> keptMoneyStartingIn(YearMonth month) {
    42	        return startingIn(month).stream().filter(r -> r.heldAmount().signum() > 0).toList();
    43	    }
    44	
    45	    private static YearMonth parse(String period) {
    46	        try {
    47	            return YearMonth.parse(period);
    48	        } catch (DateTimeParseException | NullPointerException e) {
    49	            throw new BusinessException(ErrorCode.INVALID_REQUEST, "Mês inválido, use o formato 2027-07");
    50	        }
    51	    }
    52	}
