     5	import java.util.Comparator;
     6	import java.util.List;
     7	import pousada.domain.Reservation;
     8	import pousada.error.BusinessException;
     9	import pousada.error.ErrorCode;
    10	import pousada.service.ReservationRepository;
    11	import pousada.service.RoomCatalog;
    12	
    13	public class OccupancyReport implements Report {
    14	    private final ReservationRepository repository;
    15	    private final RoomCatalog rooms;
    16	
    17	    public OccupancyReport(ReservationRepository repository, RoomCatalog rooms) {
    18	        this.repository = repository;
    19	        this.rooms = rooms;
    20	    }
    21	
    22	    @Override
    23	    public String name() {
    24	        return "occupancy";
    25	    }
    26	
    27	    @Override
    28	    public String parameter() {
    29	        return "date";
    30	    }
    31	
    32	    @Override
    33	    public ReportData generate(String period) {
    34	        LocalDate night = parse(period);
    35	        List<Reservation> occupying = repository.all().stream()
    36	                .filter(r -> r.status().isPaid() && r.occupiesNight(night))
    37	                .sorted(Comparator.comparing((Reservation r) -> r.room().number()).thenComparing(Reservation::id))
    38	                .toList();
    39	        List<List<String>> rows = occupying.stream()
    40	                .map(r -> List.of(String.valueOf(r.room().number()), r.room().type().name(),
    41	                        String.valueOf(r.id()), r.checkIn().toString(), r.checkOut().toString()))
    42	                .toList();
    43	        long occupiedRooms = occupying.stream().map(r -> r.room().number()).distinct().count();
    44	        return new ReportData(night.toString(),
    45	                List.of("room", "type", "reservation", "check_in", "check_out"), rows,
    46	                List.of("total", occupiedRooms + "/" + rooms.all().size()));
    47	    }
    48	
    49	    private static LocalDate parse(String period) {
    50	        try {
    51	            return LocalDate.parse(period);
    52	        } catch (DateTimeParseException | NullPointerException e) {
    53	            throw new BusinessException(ErrorCode.INVALID_REQUEST, "Data inválida, use o formato 2027-07-10");
    54	        }
    55	    }
    56	}
