    25	        List<List<String>> rows = Arrays.stream(RatePlan.values())
    26	                .map(plan -> row(plan, kept.stream().filter(r -> r.ratePlan() == plan).toList()))
    27	                .toList();
    28	        BigDecimal total = kept.stream().map(Reservation::heldAmount).reduce(Money.ZERO, BigDecimal::add);
    29	        return new ReportData(month.toString(), List.of("rate_plan", "reservations", "amount"), rows,
    30	                List.of("total", String.valueOf(kept.size()), total.toPlainString()));
