=== report/ReportWriter.java
     1	package pousada.report;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	import java.util.stream.Collectors;
     6	
     7	/** Único lugar que define o formato de todos os relatórios CSV. */
     8	public class ReportWriter {
     9	    private static final String INN_NAME = "Pousada Maré Alta";
    10	
    11	    public String write(Report report, ReportData data) {
    12	        List<List<String>> lines = new ArrayList<>();
    13	        lines.add(List.of(INN_NAME, report.name(), data.period()));
    14	        lines.add(data.header());
    15	        lines.addAll(data.rows());
    16	        lines.add(data.total());
    17	        return lines.stream().map(ReportWriter::line).collect(Collectors.joining("\n", "", "\n"));
    18	    }
    19	
    20	    private static String line(List<String> cells) {
    21	        return cells.stream().map(ReportWriter::cell).collect(Collectors.joining(","));
    22	    }
    23	
    24	    private static String cell(String value) {
    25	        boolean needsQuotes = value.contains(",") || value.contains("\"") || value.contains("\n");
    26	        return needsQuotes ? "\"" + value.replace("\"", "\"\"") + "\"" : value;
    27	    }
    28	}
