=== report/TourismTaxReport.java
     1	package pousada.report;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.YearMonth;
     5	import java.util.List;
     6	import pousada.domain.Money;
     7	import pousada.domain.Reservation;
     8	import pousada.service.ReservationRepository;
     9	
    10	public class TourismTaxReport extends MonthlyReport {
    11	    /** Valor da prefeitura por hóspede por noite; muda todo ano. */
    12	    static final BigDecimal TAX_PER_GUEST_NIGHT = Money.of("4.50");
    13	
    14	    public TourismTaxReport(ReservationRepository repository) {
    15	        super(repository);
    16	    }
    17	
    18	    @Override
    19	    public String name() {
    20	        return "tourism-tax";
    21	    }
    22	
    23	    @Override
    24	    ReportData generate(YearMonth month) {
    25	        List<Reservation> paid = startingIn(month).stream().filter(r -> r.status().isPaid()).toList();
    26	        List<List<String>> rows = paid.stream()
    27	                .map(r -> List.of(String.valueOf(r.id()), String.valueOf(r.room().number()),
    28	                        r.checkIn().toString(), r.checkOut().toString(), String.valueOf(r.guests()),
    29	                        String.valueOf(r.nights()), taxOf(r).toPlainString()))
    30	                .toList();
    31	        BigDecimal total = paid.stream().map(TourismTaxReport::taxOf).reduce(Money.ZERO, BigDecimal::add);
    32	        return new ReportData(month.toString(),
    33	                List.of("reservation", "room", "check_in", "check_out", "guests", "nights", "tax"), rows,
    34	                List.of("total", total.toPlainString()));
    35	    }
    36	
    37	    private static BigDecimal taxOf(Reservation r) {
    38	        return Money.round(TAX_PER_GUEST_NIGHT.multiply(BigDecimal.valueOf((long) r.guests() * r.nights())));
    39	    }
    40	}

