  1	package pousada.domain;
  2	
  3	import java.math.BigDecimal;
  4	import java.time.LocalDate;
  5	import pousada.error.BusinessException;
  6	import pousada.error.ErrorCode;
  7	
  8	public record Reservation(
  9	        int id,
 10	        Room room,
 11	        String guestName,
 12	        String guestEmail,
 13	        String guestCpf,
 14	        LocalDate checkIn,
 15	        LocalDate checkOut,
 16	        int guests,
 17	        RatePlan ratePlan,
 18	        Quote quote,
 19	        ReservationStatus status,
 20	        BigDecimal amountPaid,
 21	        BigDecimal refund) {
 22	
 23	    public int nights() {
 24	        return quote.nights();
 25	    }
 26	
 27	    public boolean overlaps(LocalDate otherCheckIn, LocalDate otherCheckOut) {
 28	        return checkIn.isBefore(otherCheckOut) && otherCheckIn.isBefore(checkOut);
 29	    }
 30	
 31	    public boolean occupiesNight(LocalDate night) {
 32	        return !checkIn.isAfter(night) && night.isBefore(checkOut);
 33	    }
 34	
 35	    public BigDecimal heldAmount() {
 36	        return refund == null ? amountPaid : amountPaid.subtract(refund);
 37	    }
 38	
 39	    public Reservation confirm() {
 40	        requireStatus("confirmada", ReservationStatus.PENDING);
 41	        return next(ReservationStatus.CONFIRMED, quote.total(), refund);
 42	    }
 43	
 44	    public Reservation doCheckIn() {
 45	        requireStatus("com check-in", ReservationStatus.CONFIRMED);
 46	        return next(ReservationStatus.CHECKED_IN, amountPaid, refund);
 47	    }
 48	
 49	    public Reservation doCheckOut() {
 50	        requireStatus("com check-out", ReservationStatus.CHECKED_IN);
 51	        return next(ReservationStatus.CHECKED_OUT, amountPaid, refund);
 52	    }
 53	
 54	    public Reservation cancel() {
 55	        requireStatus("cancelada", ReservationStatus.PENDING, ReservationStatus.CONFIRMED);
 56	        return next(ReservationStatus.CANCELLED, amountPaid, ratePlan.refundFor(amountPaid));
 57	    }
 58	
 59	    public void requirePaid() {
 60	        if (!status.isPaid()) {
 61	            throw notAllowed("A reserva não está paga");
 62	        }
 63	    }
 64	
 65	    private void requireStatus(String action, ReservationStatus... allowed) {
 66	        for (ReservationStatus s : allowed) {
 67	            if (s == status) {
 68	                return;
 69	            }
 70	        }
 71	        throw notAllowed("A reserva " + id + " não pode ser " + action + " com a situação " + status);
 72	    }
 73	
 74	    private static BusinessException notAllowed(String message) {
 75	        return new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED, message);
 76	    }
 77	
 78	    private Reservation next(ReservationStatus newStatus, BigDecimal paid, BigDecimal newRefund) {
 79	        return new Reservation(id, room, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
 80	                ratePlan, quote, newStatus, paid, newRefund);
 81	    }
 82	}
 83	package pousada.domain;
 84	
 85	public enum ReservationStatus {
 86	    PENDING(false),
 87	    CONFIRMED(true),
 88	    CHECKED_IN(true),
 89	    CHECKED_OUT(true),
 90	    CANCELLED(false);
 91	
 92	    private final boolean paid;
 93	
 94	    ReservationStatus(boolean paid) {
 95	        this.paid = paid;
 96	    }
 97	
 98	    public boolean isPaid() {
 99	        return paid;
100	    }
101	}
102	package pousada.domain;
103	
104	import java.math.BigDecimal;
105	import java.time.LocalDate;
106	
107	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
108	    private static final BigDecimal HIGH_SEASON_MARKUP = new BigDecimal("1.20");
109	
110	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
111	        BigDecimal subtotal = Money.ZERO;
112	        int nights = 0;
113	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
114	            subtotal = subtotal.add(nightPrice(room, night));
115	            nights++;
116	        }
117	        BigDecimal discount = plan.discountOn(subtotal);
118	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
119	    }
120	
121	    private static BigDecimal nightPrice(Room room, LocalDate night) {
122	        BigDecimal rate = room.nightlyRate();
123	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_MARKUP)) : rate;
124	    }
125	
126	    static boolean isHighSeason(LocalDate night) {
127	        int month = night.getMonthValue();
128	        boolean summerHoliday = month == 12 && night.getDayOfMonth() >= 15 || month == 1 || month == 2;
129	        return summerHoliday || month == 7;
130	    }
131	}
132	package pousada.domain;
133	
134	import java.math.BigDecimal;
135	
136	public enum RatePlan {
137	    STANDARD("0", true),
138	    NON_REFUNDABLE("0.15", false);
139	
140	    private final BigDecimal discountRate;
141	    private final boolean refundable;
142	
143	    RatePlan(String discountRate, boolean refundable) {
144	        this.discountRate = new BigDecimal(discountRate);
145	        this.refundable = refundable;
146	    }
147	
148	    public BigDecimal discountOn(BigDecimal subtotal) {
149	        return Money.round(subtotal.multiply(discountRate));
150	    }
151	
152	    public BigDecimal refundFor(BigDecimal amountPaid) {
153	        return refundable ? amountPaid : Money.ZERO;
154	    }
155	}
