 84	import java.util.List;
 85	import java.util.Optional;
 86	import java.util.concurrent.ConcurrentHashMap;
 87	import java.util.concurrent.atomic.AtomicInteger;
 88	import pousada.domain.Reservation;
 89	
 90	public class ReservationRepository {
 91	    private final ConcurrentHashMap<Integer, Reservation> byId = new ConcurrentHashMap<>();
 92	    private final AtomicInteger lastId = new AtomicInteger();
 93	
 94	    public int nextId() {
 95	        return lastId.incrementAndGet();
 96	    }
 97	
 98	    public void save(Reservation reservation) {
 99	        byId.put(reservation.id(), reservation);
100	    }
101	
102	    public Optional<Reservation> find(int id) {
103	        return Optional.ofNullable(byId.get(id));
104	    }
105	
106	    public List<Reservation> all() {
107	        return List.copyOf(byId.values());
108	    }
109	}
