 13	public class ReservationService {
 14	    private final RoomCatalog rooms;
 15	    private final ReservationRepository repository;
 16	    private final Notifications notifications;
 17	
 18	    public ReservationService(RoomCatalog rooms, ReservationRepository repository, Notifications notifications) {
 19	        this.rooms = rooms;
 20	        this.repository = repository;
 21	        this.notifications = notifications;
 22	    }
 23	
 24	    public synchronized Reservation create(NewReservation req) {
 25	        Room room = rooms.find(req.roomNumber())
 26	                .orElseThrow(() -> new BusinessException(ErrorCode.ROOM_NOT_FOUND, "Quarto inexistente: " + req.roomNumber()));
 27	        if (req.guests() > room.capacity()) {
 28	            throw new BusinessException(ErrorCode.CAPACITY_EXCEEDED,
 29	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
 30	        }
 31	        boolean taken = repository.all().stream()
 32	                .anyMatch(r -> r.room().equals(room)
 33	                        && r.status() != ReservationStatus.CANCELLED
 34	                        && r.overlaps(req.checkIn(), req.checkOut()));
 35	        if (taken) {
 36	            throw new BusinessException(ErrorCode.ROOM_UNAVAILABLE,
 37	                    "O quarto " + room.number() + " já está reservado em alguma das noites");
 38	        }
 39	        Quote quote = Quote.of(room, req.checkIn(), req.checkOut(), req.ratePlan());
 40	        Reservation reservation = new Reservation(repository.nextId(), room, req.guestName(), req.guestEmail(),
 41	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), req.ratePlan(), quote,
 42	                ReservationStatus.PENDING, Money.ZERO, null);
 43	        repository.save(reservation);
 44	        return reservation;
 45	    }
 46	
 47	    public Reservation get(int id) {
 48	        return repository.find(id).orElseThrow(() ->
 49	                new BusinessException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva inexistente: " + id));
 50	    }
 51	
 52	    public synchronized Reservation confirm(int id) {
 53	        Reservation confirmed = change(id, Reservation::confirm);
 54	        notifications.reservationConfirmed(confirmed);
 55	        return confirmed;
 56	    }
 57	
 58	    public synchronized Reservation cancel(int id) {
 59	        return change(id, Reservation::cancel);
 60	    }
 61	
 62	    public synchronized Reservation checkIn(int id) {
 63	        return change(id, Reservation::doCheckIn);
 64	    }
 65	
 66	    public synchronized Receipt checkOut(int id) {
 67	        return Receipt.of(change(id, Reservation::doCheckOut));
 68	    }
 69	
 70	    public Receipt receipt(int id) {
 71	        Reservation reservation = get(id);
 72	        reservation.requirePaid();
 73	        return Receipt.of(reservation);
 74	    }
 75	
 76	    private Reservation change(int id, UnaryOperator<Reservation> transition) {
 77	        Reservation changed = transition.apply(get(id));
 78	        repository.save(changed);
 79	        return changed;
 80	    }
 81	}
