    27	        LocalDate checkIn = date(json, "checkIn");
    28	        LocalDate checkOut = date(json, "checkOut");
    29	        int guests = integer(json, "guests");
    30	        if (!checkOut.isAfter(checkIn)) {
    31	            throw invalid("A saída deve ser depois da entrada");
    32	        }
