    40	    private static String text(JsonNode json, String field) {
    41	        JsonNode node = json.get(field);
    42	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    43	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    44	        }
    45	        return node.asText();
    46	    }
    47	
    48	    private static int integer(JsonNode json, String field) {
    49	        JsonNode node = json.get(field);
    50	        if (node == null || !node.isInt()) {
    51	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    52	        }
    53	        return node.asInt();
    54	    }
    55	
    56	    private static LocalDate date(JsonNode json, String field) {
    57	        try {
    58	            return LocalDate.parse(text(json, field));
    59	        } catch (DateTimeParseException e) {
    60	            throw invalid("Data inválida em " + field + ", use o formato 2027-07-10");
    61	        }
    62	    }
